'use strict';
// Public navigation never waits for an account, a whole library, or personal progress.
window.OrthodoxSite=(()=>{
 const main=document.getElementById('main'),cache=new Map(),nativeReplace=history.replaceState.bind(history);let request=null,serial=0,viewTouched=false;
 main.addEventListener('pointerdown',()=>{viewTouched=true;},{passive:true});main.addEventListener('keydown',()=>{viewTouched=true;});for(const name of ['wheel','touchmove'])addEventListener(name,()=>{viewTouched=true;},{passive:true});
 const titles={home:'Home',explore:'Explore',learn:'Learn',lesson:'Lesson',saints:'Saints',saint:'Saint',icons:'Icons',icon:'Icon',prayers:'Prayers',prayer:'Prayer',services:'Services',service:'Service',glossary:'Glossary',term:'Glossary',timeline:'History timeline',church:'Inside the church',authority:'Church authority','church-year':'Church year',account:'Account',settings:'Settings',notebook:'Study notebook',journal:'Lesson notes',library:'Search',sources:'Sources',about:'About'};
 function url(route){if(route.startsWith('#/'))route=route.slice(1);if(!route.startsWith('/'))route='/'+route;const [path,query='']=route.split('?');return (path==='/home'||path==='/'?'/':path.replace(/\/$/,'')+'/')+(query?'?'+query:'');}
 function route(){return '#/'+(location.pathname.replace(/^\/|\/$/g,'')||'home')+location.search;}
 function parts(){const [path,query='']=route().slice(2).split('?');return {parts:path.split('/').map(decodeURIComponent),params:new URLSearchParams(query)};}
 history.replaceState=(state,title,target)=>nativeReplace(state,title,typeof target==='string'&&target.startsWith('#/')?url(target):target);
 function links(root){for(const anchor of root.querySelectorAll('a[href]')){const href=anchor.getAttribute('href');if(href.startsWith('#/'))anchor.setAttribute('href',url(href));else if(href&&!/^(?:#|\/|[a-z]+:)/i.test(href))anchor.setAttribute('href','/'+href);}}
 const observer=new MutationObserver(mutations=>{for(const mutation of mutations)for(const node of mutation.addedNodes)if(node.nodeType===1){if(node.matches('a[href^="#/"]'))node.setAttribute('href',url(node.getAttribute('href')));links(node);}});observer.observe(document.body,{childList:true,subtree:true});links(document.body);
 function shell(label){const p=parts(),page=p.parts[0],section=({lesson:'learn',prayer:'prayers',saint:'saints',icon:'icons',term:'glossary',service:'services'}[page]||page);document.body.classList.toggle('landing-page',page==='home');document.getElementById('breadcrumb').textContent=label||titles[page]||page.replace(/-/g,' ');if(window.OrthodoxNavigation){const nav=document.getElementById('nav');nav.innerHTML=window.OrthodoxNavigation.markup(section);nav.dataset.section=section;links(nav);}closeMenu();}
 function closeMenu(){window.OrthodoxNavigation?.afterNavigate();document.getElementById('sidebar').classList.remove('open');const button=document.getElementById('menu-toggle');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open navigation');button.textContent='Menu';}
 const loading=label=>'<section class="library-loading"><h1>'+label.replace(/[<>&]/g,'')+'</h1><p role="status">Loading this section…</p></section>';
 async function go(target,{replace=false,pop=false}={}){
   const destination=new URL(target.startsWith('#/')?url(target):target,location.href);if(destination.origin!==location.origin){location.href=destination.href;return;}
   const current=route();dispatchEvent(new CustomEvent('orthodox-before-page',{detail:{route:current}}));request?.abort();window.OrthodoxResources.interrupt();window.ScripturePreviews?.close();window.GlossaryPreviews?.close();
   if(!pop)(replace?nativeReplace.bind(null):history.pushState.bind(history))(null,'',destination.pathname+destination.search+destination.hash);
   viewTouched=false;const token=++serial,key=destination.pathname,label=titles[parts().parts[0]]||'Library';shell(label);main.setAttribute('aria-busy','true');main.innerHTML=loading(label);main.focus({preventScroll:true});scrollTo(0,0);
   const controller=new AbortController(),release=window.OrthodoxResources.hold();request=controller;
   try{
     let html=cache.get(key);if(!html){const response=await fetch(destination.pathname,{signal:controller.signal,priority:'high'});if(!response.ok)throw Error('Unable to load this page.');html=await response.text();cache.set(key,html);while(cache.size>8)cache.delete(cache.keys().next().value);}
     if(token!==serial)return;const parsed=new DOMParser().parseFromString(html,'text/html'),next=parsed.getElementById('main');if(!next)throw Error('This page is unavailable.');main.innerHTML=next.innerHTML;main.dataset.route=route();main.dataset.static='true';main.removeAttribute('aria-busy');document.title=parsed.title;shell(parsed.getElementById('breadcrumb')?.textContent);links(main);dispatchEvent(new CustomEvent('orthodox-page',{detail:{route:route()}}));
     if(destination.hash&&!destination.hash.startsWith('#/'))document.getElementById(decodeURIComponent(destination.hash.slice(1)))?.scrollIntoView();
   }catch(error){if(token!==serial||error.name==='AbortError')return;main.removeAttribute('aria-busy');main.innerHTML='<h1>'+label+'</h1><p role="alert">This page could not be loaded. Check your connection and try again.</p><button class="primary" data-retry-page>Try again</button><p><a href="/">Home</a></p>';main.querySelector('button').onclick=()=>go(destination.href,{replace:true});}finally{release();}
 }
 document.addEventListener('click',event=>{const anchor=event.target.closest('a[href]');if(!anchor||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||anchor.target==='_blank'||anchor.hasAttribute('download'))return;const raw=anchor.getAttribute('href');if(raw.startsWith('#')&&!raw.startsWith('#/'))return;const target=new URL(raw,location.href);if(target.origin!==location.origin||/\.[a-z0-9]+$/i.test(target.pathname))return;event.preventDefault();go(target.href);});
 addEventListener('popstate',()=>go(location.href,{pop:true}));addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))go(url(location.hash),{replace:true});});
 document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('open'),button=document.getElementById('menu-toggle');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation':'Open navigation');button.textContent=open?'Close':'Menu';});
 document.getElementById('global-search').addEventListener('submit',event=>{event.preventDefault();go('/library/?q='+encodeURIComponent(document.getElementById('global-query').value));});
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();document.getElementById('global-query').focus();}});
 document.addEventListener('click',event=>{if(event.target.closest('[data-welcome-explore]')){event.preventDefault();document.getElementById('welcome-ways')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}});
 const initial=document.getElementById('welcome-home')?.outerHTML||'';
 window.OrthodoxWelcome={homeMarkup:initial,release(){},loading:(page,error)=>error?'<h1>'+titles[page]+'</h1><p role="alert">This section could not be loaded.</p><button id="retry-load">Try again</button>':loading(titles[page]||'Library'),syncAccount(){const api=window.OrthodoxAccounts;if(!api)return;const login=document.querySelector('[data-welcome-login]'),signup=document.querySelector('[data-welcome-signup]');if(login){login.textContent=api.user()?'Your account':'Log in';login.href='/account/'+(api.user()?'':'?mode=login');}if(signup)signup.hidden=Boolean(api.user());}};
 if(main.dataset.route)cache.set(location.pathname,document.documentElement.outerHTML);
 if(location.hash.startsWith('#/'))setTimeout(()=>go(url(location.hash),{replace:true}),0);
 // The reading is already visible. Attach the progress/controller layer independently.
 setTimeout(async()=>{try{for(const script of ['visuals.js','references.js','lesson-teaching.js','editorial.js','study.js','accounts.js','study-tools.js','offline.js','app.js']){await window.OrthodoxResources.script(script);await window.OrthodoxResources.yield();}}catch{const note=document.createElement('p');note.className='notice';note.setAttribute('role','status');note.textContent='Reading remains available. Reload to retry saved progress and study tools.';main.append(note);}},0);
 let fullGlossary;
 addEventListener('orthodox-resource',event=>{if(event.detail.file==='page-data/glossary.json'){fullGlossary=event.detail.value;configureGlossary();}});
 function configureGlossary(){if(fullGlossary&&window.GlossaryPreviews){window.__fullGlossaryReady=true;window.GlossaryPreviews.configure(fullGlossary,new Map(fullGlossary.sources.map(s=>[s.id,s])));}}
 setTimeout(async()=>{try{await window.OrthodoxResources.script('scripture-references.js');await window.OrthodoxResources.script('scripture-previews.js');await window.OrthodoxResources.yield();await window.OrthodoxResources.script('glossary-previews.js');configureGlossary();}catch{}},1200);

 return {go,url,route,parts,links,interacted:()=>viewTouched,root:window.OrthodoxResources.root};
})();
